INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7ace8857-8d0e-4011-8392-e9d131cd8fa5', '3f5992c7-c724-4108-b707-e7e312f99178', 0, 'A presumptive diagnosis of angina, since chest pain is a classic anginal symptom');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('700c3ba9-8948-4ad0-bdc7-139f01463e1a', '3f5992c7-c724-4108-b707-e7e312f99178', 1, 'The documented sign/symptom (chest pain) itself, since outpatient guidelines direct coding to the highest degree of certainty and prohibit coding a ruled-out or unconfirmed condition as if it existed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('923ccf06-3cd2-4000-8716-345b2a4b4afb', '3f5992c7-c724-4108-b707-e7e312f99178', 2, 'Acute MI, since that was the reason for the workup');
