INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ee1908a1-e885-4d81-822f-33e72dc6da91', '27f8bdff-55de-415d-b15b-f74e8e8f09a0', 0, 'Coding only the screening Z code, since the encounter began as a screening');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('59446b88-f4f4-45c4-a318-2f61ecd63892', '27f8bdff-55de-415d-b15b-f74e8e8f09a0', 1, 'Coding both the screening intent (as appropriate, often via a Z code or per payer-specific screening-to-diagnostic guidance) and the actual procedure/finding (polypectomy, and the polyp as the diagnosis) reflecting what was actually done and found');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3861678f-3a2f-44d1-822e-6978fa8153a5', '27f8bdff-55de-415d-b15b-f74e8e8f09a0', 2, 'Rescheduling the polypectomy as a separate encounter regardless of what was actually performed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f768e3d7-bda0-47a8-95e4-21551c0479cb', '27f8bdff-55de-415d-b15b-f74e8e8f09a0', 3, 'Coding only the polyp diagnosis, never any screening-related code');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
