INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3f852ac7-039b-42d2-9137-e7421dcb90a2', 'dec71dd4-fb94-48b5-bbbf-4c7611bed795', 0, 'A resolved childhood illness noted only in passing in the social history section');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('13ff274c-1ffa-49b1-a1c4-0724727824d1', 'dec71dd4-fb94-48b5-bbbf-4c7611bed795', 1, 'A urinary tract infection newly diagnosed during the stay and treated with a full course of antibiotics');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8e181afb-a7c4-4799-b7ee-a47701228388', 'dec71dd4-fb94-48b5-bbbf-4c7611bed795', 2, 'A family history of diabetes noted in the intake form');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8def029e-771a-420d-a07e-f5765ada579d', 'dec71dd4-fb94-48b5-bbbf-4c7611bed795', 3, 'An allergy to penicillin listed in the allergy band with no other documentation');
