INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0d7012b4-3b8f-4d83-b483-d67594b16477', 'e2aaa6a3-03e9-4641-a709-cf5bd0fa6b27', 2, 'Extraction');
