INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a37d97cc-262f-460c-9c87-dbdc466aca60', '5e237299-89c4-4ff6-82c2-a70434be820c', 1, 'Extirpation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9fcae239-43e9-4d6b-bb5c-2f69fa0bf7db', '5e237299-89c4-4ff6-82c2-a70434be820c', 2, 'Irrigation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('af2f33e7-539b-4bb8-92e2-8884d4fffa01', '5e237299-89c4-4ff6-82c2-a70434be820c', 3, 'Fragmentation');
