INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e590212f-2a4b-41f5-8730-9b500afe1eb2', 'abec1d9a-48bb-4dd1-af05-d52658ed4145', 0, 'Fragmentation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5290c784-3f84-4e5a-9b97-f9c0359e9090', 'abec1d9a-48bb-4dd1-af05-d52658ed4145', 1, 'Extirpation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f7b8e397-00fd-42cc-bef3-c4a1d1a7e31c', 'abec1d9a-48bb-4dd1-af05-d52658ed4145', 2, 'Destruction');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6879668a-c644-467a-bf49-9beade577363', 'abec1d9a-48bb-4dd1-af05-d52658ed4145', 3, 'Division');
