INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c73395de-5696-468f-98ae-1961d6f1374c', 'b749a449-667b-4524-93e7-db379788d5b7', 0, 'Automatically assign a sepsis code, since ''urosepsis'' always means sepsis due to a UTI');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0ac86178-1a4f-445f-9737-c15f46b8d9bb', 'b749a449-667b-4524-93e7-db379788d5b7', 1, 'Recognize that ''urosepsis'' is a nonspecific, sometimes inconsistently used term that does not map cleanly to a single ICD-10-CM code, and query the provider for clarification of the actual intended diagnosis (e.g., UTI alone vs. sepsis due to UTI) rather than assume');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a1c801ae-4702-458b-a66d-66e476063823', 'b749a449-667b-4524-93e7-db379788d5b7', 2, 'Code it as a simple, uncomplicated UTI only, since sepsis can never be assumed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b8b34a58-9a8e-4c9a-9e74-8818bc2e0351', 'b749a449-667b-4524-93e7-db379788d5b7', 3, 'Ignore the diagnosis entirely as uncodeable and non-billable');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('760dba0c-183b-475a-b402-e5e056ba4dfa', 'b9e9b540-be2f-41df-9405-a306a0de83db', 0, 'Coding the procedure as if it had been performed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c7e40a62-9cf8-4e0b-8073-8e58952b57c4', 'b9e9b540-be2f-41df-9405-a306a0de83db', 1, 'Coding the reason for the encounter (e.g., the condition prompting the scheduled procedure) along with an appropriate code/status reflecting the canceled procedure per applicable guidance, rather than coding a procedure that did not occur');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c7426895-d5c9-4fa5-9296-6cf5c8bccd8b', 'b9e9b540-be2f-41df-9405-a306a0de83db', 2, 'No code may ever be assigned for a canceled encounter');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f3b08bb3-febe-4542-a4fd-526b1d2d6c28', 'b9e9b540-be2f-41df-9405-a306a0de83db', 3, 'Coding a random procedure code closest to what was scheduled');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('560b2f0d-a0cd-4626-8b99-c9ee7be0f521', 'fe58af0e-0ee8-44e5-86dc-5e730b2f9e03', 0, 'A routine, expected postoperative finding requiring no code at all');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9108af1d-d45e-4e87-9582-ae32d5203938', 'fe58af0e-0ee8-44e5-86dc-5e730b2f9e03', 1, 'An additional diagnosis (and, per documentation, potentially a postoperative complication code if the provider has documented the causal relationship to the procedure), since it required clinical evaluation/treatment and is explicitly linked by the provider');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8521d664-815a-40ea-be5e-818e27d21ad7', 'fe58af0e-0ee8-44e5-86dc-5e730b2f9e03', 2, 'Only as a symptom code for blood loss, never a defined anemia code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8d7806d1-1621-4ea9-b4f2-13b53fd77152', 'fe58af0e-0ee8-44e5-86dc-5e730b2f9e03', 3, 'Automatically excluded from coding because blood loss is inherent to any surgery');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('18ae78e5-4bf7-41e2-973e-5da2cf9d92f9', '85ced809-3b92-4c8f-94a0-877e40924266', 0, 'Transplantation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0cea56d4-3f23-4ad3-8074-f6409b55a177', '85ced809-3b92-4c8f-94a0-877e40924266', 1, 'Replacement');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('42d88fed-4b69-4867-b1eb-b2f0d3b1f96d', '85ced809-3b92-4c8f-94a0-877e40924266', 2, 'Supplement');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cc245f66-efd7-44a1-a530-22904e375da1', '85ced809-3b92-4c8f-94a0-877e40924266', 3, 'Restoration');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('dfd132ee-b235-48fa-9e98-75c6589ec369', '57fc09b3-4ade-4f22-bfb0-182281fbf0ca', 0, 'Only one code is ever assigned regardless of how many distinct devices/qualifiers (autograft types) are used');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b97c71f8-f5f3-453c-8d57-80b8889dc51b', '57fc09b3-4ade-4f22-bfb0-182281fbf0ca', 1, 'Bypass procedures require attention to the specific qualifier value representing the type of graft material used for each distinct vessel bypassed, since a single ''bypass'' code doesn''t capture graft-source detail without the qualifier, and multiple distinct body part/qualifier combinations may require multiple codes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f0892a99-57bd-46e9-84b1-ed092ebbb3ec', '57fc09b3-4ade-4f22-bfb0-182281fbf0ca', 2, 'Bypass procedures are never separately coded from the underlying diagnosis');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c207482b-d61b-4808-8afd-16be4f0aa3a0', '57fc09b3-4ade-4f22-bfb0-182281fbf0ca', 3, 'CABG is always coded with a single generic ''heart surgery'' code regardless of technique');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6c37e2ce-2d7b-4619-82af-cb6219324696', 'e3e2b10c-c315-4870-850c-8569d2cf9699', 0, 'The aspiration pneumonia must always be sequenced as principal diagnosis regardless of the reason for admission');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('814bf050-717a-457f-80da-21cd493db15f', 'e3e2b10c-c315-4870-850c-8569d2cf9699', 1, 'The principal diagnosis remains governed by UHDDS''s ''condition established after study to be chiefly responsible for occasioning admission'' — here, likely the stroke, since the pneumonia developed as a complication during the stay, with the pneumonia coded as an additional diagnosis (and potentially with a code also indicating the causal link, per documentation)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ac88f5ee-2c18-4a29-be39-3a8bcc6e5c16', 'e3e2b10c-c315-4870-850c-8569d2cf9699', 2, 'Only one of the two conditions may ever be coded');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('53d37af3-40b3-4a9f-a9f0-86e9210db8ea', 'e3e2b10c-c315-4870-850c-8569d2cf9699', 3, 'The two conditions must be coded as a single combination code, which does not exist for this scenario');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7d2fa6f5-5d7c-4d08-b4b4-98a1240d2d26', '0f1a7c14-ebb5-4432-9865-daae7937cd14', 0, 'Injury, poisoning, and certain other external-cause-related conditions, and specific chapters like pregnancy/obstetric codes and certain musculoskeletal conditions');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('77709a59-48f7-4146-b6af-ee5629c30aee', '0f1a7c14-ebb5-4432-9865-daae7937cd14', 1, 'Every single ICD-10-CM code without exception');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('92835e0e-dbd7-4697-9221-5fe5d02f2768', '0f1a7c14-ebb5-4432-9865-daae7937cd14', 2, 'Only codes beginning with the letter Z');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('52c0c86d-107b-4a46-9561-bf6c1f421293', '0f1a7c14-ebb5-4432-9865-daae7937cd14', 3, 'Only codes for chronic conditions');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3ab898ad-5a8c-4580-a19b-70b6718f50d8', 'a98ad227-4e63-454d-b9aa-de912a2c6a5b', 0, 'Truncating the extension and omitting it entirely');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ff103c1b-3f5f-402f-ad33-ff0c67407afc', 'a98ad227-4e63-454d-b9aa-de912a2c6a5b', 1, 'Using ''X'' as a placeholder to fill any empty characters so the 7th character extension is in the correct final position');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1377ad61-69a3-4574-b7c5-e4961294c4c5', 'a98ad227-4e63-454d-b9aa-de912a2c6a5b', 2, 'Adding the extension immediately after the 3rd character regardless of code length');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4d92ff77-9a6e-4a95-9f73-e1ed49c348b7', 'a98ad227-4e63-454d-b9aa-de912a2c6a5b', 3, 'Never using that code at all');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('de22af34-9fa5-4ac1-a0dd-316612754bd9', '7531bb6c-8961-4ac3-92ab-cf66fdb893bd', 0, 'Can never be assigned unless the physician personally documents the exact BMI value');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8877f678-006b-453a-b6ad-3ef0e36f6b5a', '7531bb6c-8961-4ac3-92ab-cf66fdb893bd', 1, 'May be based on documentation from clinicians who are not the patient''s provider (e.g., a dietitian, nurse) for the BMI value itself, as long as the associated diagnosis (e.g., obesity) is documented by a provider — BMI is one of a small set of exceptions to the general ''provider must document the diagnosis'' rule');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('734e8740-39ca-42cf-b734-96dba992742c', '7531bb6c-8961-4ac3-92ab-cf66fdb893bd', 2, 'Are always coded regardless of whether obesity itself is a documented diagnosis');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ff394760-31b5-450d-94d7-795bfa2a046e', '7531bb6c-8961-4ac3-92ab-cf66fdb893bd', 3, 'Require a query before ANY BMI code may ever be used');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('831e29fa-77cf-4555-9ed7-73c318014c47', '7905071c-31ef-481d-8de6-5d807f3418bd', 0, 'As a default, preferred first choice whenever multiple specific code options exist, to save coder time');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b0048c9d-19d4-47d8-a980-57f6df0b670d', '7905071c-31ef-481d-8de6-5d807f3418bd', 1, 'When the medical record genuinely does not provide enough information for a more specific code, and further clarification is not reasonably obtainable (e.g., truly not documented, and query would not add value)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('78817bc8-7575-4285-b7dc-55bd080d716f', '7905071c-31ef-481d-8de6-5d807f3418bd', 2, 'Only for outpatient encounters, never inpatient');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c176c85f-a1f6-4007-89ab-00b4d46e2e66', '7905071c-31ef-481d-8de6-5d807f3418bd', 3, 'Only when a coder personally disagrees with the physician''s more specific documented diagnosis');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('36bab092-1cf8-4d96-971f-40eff884b190', '9f6ff26e-84af-4a35-a3fa-274c75710bcc', 0, 'Supplement');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('79588681-1251-4d1d-9583-380b80d830f8', '9f6ff26e-84af-4a35-a3fa-274c75710bcc', 1, 'Replacement');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e7db943c-a6fa-4039-9624-5b71f9a8a868', '9f6ff26e-84af-4a35-a3fa-274c75710bcc', 2, 'Insertion');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5817d00b-a228-48ee-972f-eeda10ae9a46', '9f6ff26e-84af-4a35-a3fa-274c75710bcc', 3, 'Restriction');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5be8a2dd-7968-4bb6-b3b3-f4e552831ad3', '5f851de2-a339-468b-8333-8dbabd1724ed', 0, 'Supplement');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1a268561-d8b9-4696-a4f7-da03e799ac0b', '5f851de2-a339-468b-8333-8dbabd1724ed', 1, 'Insertion');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e2091efd-0b50-41d1-a3e0-7c93ed987169', '5f851de2-a339-468b-8333-8dbabd1724ed', 2, 'Replacement');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cbafb37a-21f9-42a4-9d8e-4a16ebca0c56', '5f851de2-a339-468b-8333-8dbabd1724ed', 3, 'Repair');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('92c1f486-31a7-4f52-8b27-31cef29018be', '0867cfa3-25bd-492a-8099-386be602561b', 0, 'Acute respiratory failure may be sequenced as principal diagnosis if it is the condition that, after study, was chiefly responsible for occasioning the admission, even when another condition (e.g., pneumonia) is also present — sequencing is not automatically dictated by disease type');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c41c164a-df50-47cb-a290-dd3affa3beda', '0867cfa3-25bd-492a-8099-386be602561b', 1, 'Acute respiratory failure may never be sequenced as principal diagnosis under any circumstance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a9c65d07-16e7-41e7-bfaa-5317470ce986', '0867cfa3-25bd-492a-8099-386be602561b', 2, 'Pneumonia must always be sequenced first whenever respiratory failure and pneumonia coexist');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2e5efb98-c4dd-4e8c-9bab-cf0fbe22d31d', '0867cfa3-25bd-492a-8099-386be602561b', 3, 'The two conditions must always be combined into a single code');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b9267759-ca02-42af-9b18-d69ae0c25a4b', '46ed7483-4457-4b8d-91a4-608492c96160', 0, 'An active sepsis code, since sepsis was previously documented');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ec0b763f-8963-4b53-83a9-f34cf508755f', '46ed7483-4457-4b8d-91a4-608492c96160', 1, 'A personal history code (Z code) if clinically relevant to the current encounter, not an active-infection code, since the condition is documented as resolved and not currently present');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f531caae-caa8-45b7-8e9f-fa4114813afe', '46ed7483-4457-4b8d-91a4-608492c96160', 2, 'The same code as an active principal diagnosis for this admission');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fb005cc1-be74-4580-a943-a49bba625bad', '46ed7483-4457-4b8d-91a4-608492c96160', 3, 'No code at all, regardless of relevance to current care');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7f5b2041-bddd-4abe-925e-4ede823b7bfd', 'b202c230-6a20-42fc-8d50-060e2f731750', 0, 'Removal');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ade4e17d-9a6e-4d9b-ba12-bd6afe3f3ef0', 'b202c230-6a20-42fc-8d50-060e2f731750', 1, 'Revision');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b236664e-acae-40d6-b5a1-755f9c23b765', 'b202c230-6a20-42fc-8d50-060e2f731750', 2, 'Change');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fea5f689-e5ea-4b09-999c-b636e433c781', 'b202c230-6a20-42fc-8d50-060e2f731750', 3, 'Extraction');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1edab567-e8ae-4e79-b981-971aad13ce34', '11de4ddd-56eb-4252-b93a-24e709a61b10', 0, 'Change');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('501243ab-85e3-4c53-a07c-1834c1ad5a4d', '11de4ddd-56eb-4252-b93a-24e709a61b10', 1, 'Removal');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4da2cf19-fa8f-4e47-8c4b-0818753e35db', '11de4ddd-56eb-4252-b93a-24e709a61b10', 2, 'Revision');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('590afac1-cd4a-4271-9197-47e8baeca02b', '11de4ddd-56eb-4252-b93a-24e709a61b10', 3, 'Replacement');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1eb6180e-4b83-48a8-83e1-c099f813d5cc', '1915faaa-0097-4ac8-bfd7-13cfbddff432', 0, 'Always code every chronic condition on the problem list regardless of relevance to the visit');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8a19be43-df24-4fb1-8d8a-b9d5bce3ae4f', '1915faaa-0097-4ac8-bfd7-13cfbddff432', 1, 'Code chronic conditions that coexist and impact patient care, treatment, or management for the encounter — a stable condition explicitly not addressed/evaluated during this specific encounter may not need separate reporting depending on payer/facility coding policy and guideline application, though many organizations do report chronic conditions actively being managed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1a30442c-1535-4727-b181-9fcc89e1feed', '1915faaa-0097-4ac8-bfd7-13cfbddff432', 2, 'Never code any chronic condition in the outpatient setting');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('610e8e9f-184e-4d86-a0e5-cdaa010a1407', '1915faaa-0097-4ac8-bfd7-13cfbddff432', 3, 'Only code conditions that are the primary reason for the visit');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('803781fc-f8d3-4db8-834d-e0fb0f2d9a9b', 'a76d68b6-7b2c-45f0-8d53-d3f39c0e236c', 0, 'DKA is coded as a completely separate, unrelated diagnosis from diabetes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2c0070f6-cb80-4f60-839e-dd17029d4c9e', 'a76d68b6-7b2c-45f0-8d53-d3f39c0e236c', 1, 'ICD-10-CM''s diabetes combination codes include a specific code for type 2 diabetes with ketoacidosis, reflecting the direct diabetes-DKA relationship within the classification itself');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8871a9e6-f508-4708-a8a0-721472180e75', 'a76d68b6-7b2c-45f0-8d53-d3f39c0e236c', 2, 'DKA can only be coded as a manifestation of type 1 diabetes, never type 2');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4769b988-d373-4cc4-98ed-19b4deb62b9b', 'a76d68b6-7b2c-45f0-8d53-d3f39c0e236c', 3, 'A query is always mandatory before DKA can ever be coded with diabetes');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cdd19e70-f915-41f8-a419-41106e70326a', '616bac63-0037-465f-9ff7-b2e4e2fb279a', 0, 'It is purely advisory and may be disregarded by the coder');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2a93ef6b-9d88-4df9-8f1f-3626fcb0597c', '616bac63-0037-465f-9ff7-b2e4e2fb279a', 1, 'It is a sequencing instruction requiring the underlying condition to be sequenced before the code carrying the note (commonly seen with manifestation codes that cannot be reported as principal/first-listed diagnosis alone)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8b5ae868-46d2-4ac1-a081-bc2061a5cf2f', '616bac63-0037-465f-9ff7-b2e4e2fb279a', 2, 'It means the noted code should never be used under any circumstance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4e41cf4a-12a1-4674-ab85-ac96f7955b1e', '616bac63-0037-465f-9ff7-b2e4e2fb279a', 3, 'It applies only to procedure codes, never diagnosis codes');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ecb5cfd4-4eff-4c0b-87f8-7896be3e79e8', '937ebdee-443c-439e-9780-2c3e5aa481b9', 0, 'The exact same mandatory-first-sequencing requirement as ''code first,'' just worded differently');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('de8d0f8b-7327-4ded-a825-326f58c28f08', '937ebdee-443c-439e-9780-2c3e5aa481b9', 1, 'That the code with the note may need an additional code (sequenced after it) to fully capture the clinical picture, but the noted code itself is not restricted from being sequenced first — the reverse-direction sibling of the ''code first'' convention');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ab22bd24-c55d-4a7f-93eb-56520817ef76', '937ebdee-443c-439e-9780-2c3e5aa481b9', 2, 'That no additional code should ever be assigned');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1256ff27-150b-43f9-9cf6-ae00926ba4bd', '937ebdee-443c-439e-9780-2c3e5aa481b9', 3, 'That the additional code is optional and coders may disregard it freely');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('61501bd3-2ab8-462a-a3cf-0fcced6d0256', '4b606836-1685-4539-b0cb-e376859c9564', 0, 'A generic, unspecified heart failure code only, since acuity distinctions don''t exist in ICD-10-CM');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('86a76c88-b70f-4b3a-b854-6e745481c780', '4b606836-1685-4539-b0cb-e376859c9564', 1, 'A specific combination code capturing both the chronicity and the acute-on-chronic nature along with the systolic/diastolic/combined type, when documented (e.g., acute on chronic systolic heart failure)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f87526b5-18f9-4fcc-b0b7-46b558b7ac49', '4b606836-1685-4539-b0cb-e376859c9564', 2, 'Two entirely separate, unrelated heart failure codes reported together');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d2048180-36e0-4960-899f-a80f73dab903', '4b606836-1685-4539-b0cb-e376859c9564', 3, 'Coding only the chronic form, ignoring the acute exacerbation');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('48d5fbc4-1585-4eb4-bc79-5b12a2d7557e', '826e846a-9bd8-47c2-a704-4cc78dbf5a92', 0, 'They are interchangeable and either may be used regardless of whose history is being documented');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5e6f3493-1ae3-42da-bba5-aaacfd04fcbc', '826e846a-9bd8-47c2-a704-4cc78dbf5a92', 1, 'Personal history codes reflect a condition the PATIENT previously had that no longer exists but may affect current care; family history codes reflect a condition in a BLOOD RELATIVE that may affect the patient''s own risk — using the wrong one misrepresents whose condition is being reported');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9fece1cf-3a1f-4391-88f0-17bf950a00d2', '826e846a-9bd8-47c2-a704-4cc78dbf5a92', 2, 'Family history codes are never valid in the inpatient setting');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('95bcfa2d-9c27-4278-b673-d21df4b76185', '826e846a-9bd8-47c2-a704-4cc78dbf5a92', 3, 'Personal history codes can only be used for surgical history, never medical history');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fffab9e3-362f-4655-b1ca-96dd79ccd506', '705d5613-ee0b-4a5f-8833-b54fc685719b', 0, 'Using traumatic fracture codes and coding conventions (e.g., injury 7th characters for routine/delayed healing) exactly the same as any other traumatic fracture');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('24b0db15-a82f-455a-93f5-72400e5eea86', '705d5613-ee0b-4a5f-8833-b54fc685719b', 1, 'Using the specific pathological fracture code category (with its own distinct coding conventions and 7th character options, e.g., for fractures due to osteoporosis), which is classified separately from traumatic fracture codes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ad9a9845-3dc5-4977-be6a-0806e3741432', '705d5613-ee0b-4a5f-8833-b54fc685719b', 2, 'Coding only osteoporosis, with no fracture code at all');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('419dc516-05f6-4411-aa8c-690c0aa94c3a', '705d5613-ee0b-4a5f-8833-b54fc685719b', 3, 'Coding the fracture as traumatic and osteoporosis as an unrelated secondary condition with no combination logic');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7416ce2c-29c6-415c-abdc-5fb272d488fd', '7aa7da7f-dc4f-4417-a12e-451dc1a3dbf7', 0, 'Code the acute CVA code plus the dysphagia code together as if the stroke were still acute');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cce290a7-362e-4820-b4b6-4d710b62cd89', '7aa7da7f-dc4f-4417-a12e-451dc1a3dbf7', 1, 'Code the residual condition (dysphagia) first, followed by the sequela code for the CVA (with the appropriate 7th character ''S'' extension where applicable, or the specific late-effects code category), per the sequela coding convention which generally sequences the residual/current condition first unless the classification/index directs otherwise');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5cf7b639-6fce-499d-914b-092043a57d1a', '7aa7da7f-dc4f-4417-a12e-451dc1a3dbf7', 2, 'Only code the historical CVA, never the current residual condition');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('35aa32eb-a11d-4316-9776-3e81099b9109', '7aa7da7f-dc4f-4417-a12e-451dc1a3dbf7', 3, 'Sequela conditions are never separately coded from the causing event');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('db56c5ce-2f47-4cc5-ad20-df563ee59fb9', 'ef334e70-834b-4185-bf73-a4d6795d65bb', 0, 'Assigning a code for ''malignant neoplasm of unspecified site'' as the primary, since a specific primary was never identified');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a9ea7e40-fcb4-42d4-82a2-a69d29ee60c1', 'ef334e70-834b-4185-bf73-a4d6795d65bb', 1, 'Never coding any malignancy at all if the primary site is unknown');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6d346173-1085-4bf0-8f95-13f6a1d65335', 'ef334e70-834b-4185-bf73-a4d6795d65bb', 2, 'Coding only the metastatic sites, with no code at all reflecting the primary malignancy concept');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('32121818-e59e-49fb-852a-0337812d2856', 'ef334e70-834b-4185-bf73-a4d6795d65bb', 3, 'Querying is always mandatory before any neoplasm code may be used, with no unspecified-primary code ever being appropriate');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8bdab718-9eab-4f82-9a6a-167b23500ded', '57b4aa52-54b9-43be-9e65-70715456e3d0', 0, 'They follow the same ''code as confirmed'' inpatient uncertain-diagnosis logic used for probable/suspected conditions, when documented at the time of discharge for an inpatient stay');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('572d13c7-13ca-41be-a2c0-3b8cf4ee0608', '57b4aa52-54b9-43be-9e65-70715456e3d0', 1, 'They can never be coded under any circumstances');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3aadd78b-2160-4d69-936f-22b1fe540995', '57b4aa52-54b9-43be-9e65-70715456e3d0', 2, 'They are always coded as the fully developed, completed condition regardless of setting');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0e65cf25-6363-4f4e-ac8d-c7f04abd0f4f', '57b4aa52-54b9-43be-9e65-70715456e3d0', 3, 'They are treated identically to sequela/late-effect codes');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('aa9f79a3-b345-48b2-8803-d98ccd328438', 'b30b2fb0-3683-4639-922a-64dd41adfc1c', 0, 'Assign the unspecified anemia code automatically without further review, since ''no further specification'' ends the inquiry');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6ed1626c-af63-49c8-83f6-8208450d7a5b', 'b30b2fb0-3683-4639-922a-64dd41adfc1c', 1, 'Review the actual lab findings/workup documented in the record to see whether the physician''s own documented clinical reasoning (even if the exact ICD-10-CM term isn''t used verbatim) supports a more specific, already-established diagnosis, and query if genuinely still unclear after that review');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e0e3c370-9358-479d-a8b7-7cd3c23584f8', 'b30b2fb0-3683-4639-922a-64dd41adfc1c', 2, 'Assume the most common type of anemia by population prevalence');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cd80eac1-1be8-43ba-a9b9-9160f6d98c12', 'b30b2fb0-3683-4639-922a-64dd41adfc1c', 3, 'Refuse to code anemia at all since it lacks a type');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a81897c6-861c-469d-926b-632b78496615', '4e34dee5-b78d-45b0-88c1-7d4e0e8ea75d', 0, 'They are the principal/first-listed diagnosis in virtually all cases involving an injury');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7aa6101a-c0ff-4ab9-bfee-ec80eae469a1', '4e34dee5-b78d-45b0-88c1-7d4e0e8ea75d', 1, 'They provide additional data about how an injury/condition occurred (cause, intent, place, activity, status) and are reported as secondary/additional codes, not as the principal or first-listed diagnosis, per the Official Guidelines');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('82e4fb41-d266-4ae7-9a85-d81224bb91cf', '4e34dee5-b78d-45b0-88c1-7d4e0e8ea75d', 2, 'They replace the need for coding the actual injury/condition itself');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0f59cd3a-ece3-43f7-98c9-fa29a9661a9b', '4e34dee5-b78d-45b0-88c1-7d4e0e8ea75d', 3, 'They apply only to motor vehicle accidents');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8356eeb7-c5e5-421b-9384-4980afb31d90', '3f527a0b-5dec-44d8-93da-9a6f723210b1', 0, 'The unspecified acute pancreatitis code (or the most specific code the actual documented findings DO support) is appropriate, since the classification includes options for cases without a determinable specific cause and guidelines don''t require inventing a cause that isn''t clinically supported');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2bd62e29-d10f-46fb-9603-5ef63a64e52e', '3f527a0b-5dec-44d8-93da-9a6f723210b1', 1, 'A cause must always be assumed and coded even without clinical support');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('29c3a9cd-1db0-459c-b963-21a5443ad97e', '3f527a0b-5dec-44d8-93da-9a6f723210b1', 2, 'No code for pancreatitis may be assigned without an identified cause');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f61de550-39fb-4338-9f11-6cd7e690af3a', '3f527a0b-5dec-44d8-93da-9a6f723210b1', 3, 'Idiopathic pancreatitis and unspecified pancreatitis are coded identically in all cases with no distinction ever available');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('56136875-55e7-473e-bc5a-37d65e94bb62', 'd4a0bfb2-fb13-405f-99f2-db130b8d5eed', 0, 'CKD stage is never separately coded; only ''CKD, unspecified'' exists as an option');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('44c7bbb3-749e-4bcc-a668-5c1c36c1570b', 'd4a0bfb2-fb13-405f-99f2-db130b8d5eed', 1, 'ICD-10-CM includes specific codes for CKD stages 1 through 5 (and stage 5 requiring dialysis, i.e., end-stage renal disease), allowing the classification to capture disease severity when documented');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c233d104-7175-4cbe-90a4-1642e995ec2e', 'd4a0bfb2-fb13-405f-99f2-db130b8d5eed', 2, 'CKD staging is captured only through a separate HCPCS code, never through ICD-10-CM itself');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5dc799e0-c627-4135-b0b1-30c2c893526c', 'd4a0bfb2-fb13-405f-99f2-db130b8d5eed', 3, 'CKD stage must always be confirmed via biopsy before any stage-specific code may be used');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0d4ef147-e6c9-4949-bbfb-4ba3aa89027c', '32199abc-ab3a-4ca4-9842-51409da1c561', 0, 'Two entirely separate encounters requiring two separate principal diagnoses with no relationship to each other');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('99c5b19e-9717-4f39-9ec5-84ce4e7dbe74', '32199abc-ab3a-4ca4-9842-51409da1c561', 1, 'A single inpatient stay for coding/UHDDS reporting purposes once formally converted to inpatient, with principal diagnosis determined per the UHDDS definition based on the entire course of the stay, not artificially split at the conversion point');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('26f78710-cf46-499a-ad3a-051063179f44', '32199abc-ab3a-4ca4-9842-51409da1c561', 2, 'Only the observation portion is ever coded; the inpatient portion is disregarded');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('191600e4-312e-4bdb-9117-d00917fccf99', '32199abc-ab3a-4ca4-9842-51409da1c561', 3, 'The stay must be coded twice, once under each status, for the same set of diagnoses');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7f766199-88c5-44b3-8c62-8188cbce31b6', '898d2235-1484-4b49-9bf9-a58fbd330dd9', 0, 'The malignancy is automatically the principal diagnosis regardless of the reason for this specific admission');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('eda9aa78-350c-41ff-a1e0-713888e02857', '898d2235-1484-4b49-9bf9-a58fbd330dd9', 1, 'The dehydration remains the principal diagnosis if it is the condition established after study to be chiefly responsible for occasioning this particular admission, with the malignancy reported as an additional diagnosis, since UHDDS selection is anchored to the reason for THIS admission, not overall disease severity');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('dace8f68-84c4-4f9e-9e48-551a4274b48b', '898d2235-1484-4b49-9bf9-a58fbd330dd9', 2, 'No principal diagnosis can be assigned when a malignancy is discovered incidentally');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('af4f21e8-1aa6-484f-94f0-37a7a62b56a5', '898d2235-1484-4b49-9bf9-a58fbd330dd9', 3, 'The two conditions are always combined into a single code');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b8e3f504-782f-4115-9215-928a91d2cb84', '0a60b89e-f9b2-492f-9946-9d54a2b97686', 0, 'The preoperative ''possible'' diagnosis only');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bea6c880-d989-409a-b13d-6042fc13e6e7', '0a60b89e-f9b2-492f-9946-9d54a2b97686', 1, 'The postoperative/confirmed diagnosis, since outpatient coding should reflect the most definitive diagnosis established by the time of coding — the confirmed pathology finding, not the preoperative uncertain impression');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f4ef4c10-c606-4a0c-933b-9817f61277ee', '0a60b89e-f9b2-492f-9946-9d54a2b97686', 2, 'Neither; only symptoms may be coded');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('21f80070-b5e3-43ce-bde0-281205a07304', '0a60b89e-f9b2-492f-9946-9d54a2b97686', 3, 'Both are coded as co-equal principal diagnoses');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f9f064fa-ed1d-4d3c-aad6-733325810e12', 'd80bd6fe-3a64-474d-b571-5bb84bf47802', 0, 'Provider query construction only, never documentation review');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('08e6f694-6b5c-40d2-ad6f-c722d67ff1ad', 'd80bd6fe-3a64-474d-b571-5bb84bf47802', 1, 'Resolving conflicting documentation within the health record, since an allergy discrepancy is a patient-safety-relevant documentation-integrity issue requiring resolution, not something to leave unaddressed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8eddd50f-f252-492c-9b3d-3c51ef26f652', 'd80bd6fe-3a64-474d-b571-5bb84bf47802', 2, 'HITECH breach reporting');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c6abce57-73e0-46ce-aa4e-96006d82358e', 'd80bd6fe-3a64-474d-b571-5bb84bf47802', 3, 'DRG/grouper software configuration');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0a95eb19-87db-4e84-81ee-201c6b626f70', '3a83c977-7875-4304-9417-caf493a91da7', 0, 'Refuse to code until a single consolidated note exists');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cd9af9f0-4893-49e4-a893-9ed806b14327', '3a83c977-7875-4304-9417-caf493a91da7', 1, 'Review and synthesize all legitimately authenticated documentation pertaining to that procedure/episode of care to support accurate code assignment, since the complete health record — not necessarily a single document — is the basis for coding');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0a221976-346a-4b1e-8ff4-a4f320a0e1a9', '3a83c977-7875-4304-9417-caf493a91da7', 2, 'Code only from the brief stub, ignoring the later detailed dictation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6c19a276-b1a5-4e3a-9215-f31fb602d330', '3a83c977-7875-4304-9417-caf493a91da7', 3, 'Query the provider automatically without first reviewing the existing documentation already available');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2c9b337c-3bd4-4320-b5e2-f1b7ec6bed34', '99209422-ef8f-40b5-abd0-6501025dad4d', 0, 'Assuming based on the coder''s general clinical instinct on a case-by-case basis');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e8b1e2d7-357c-43f1-b746-007822f42883', '99209422-ef8f-40b5-abd0-6501025dad4d', 1, 'Clarifying the intended meaning via the specific patient''s clinical context (other documentation in that chart) where possible, and querying the provider when genuinely ambiguous — plus flagging the abbreviation pattern for broader documentation-improvement/abbreviation-policy review');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c0ac2e1c-a8cf-4c22-a7ff-4947c238e64d', '99209422-ef8f-40b5-abd0-6501025dad4d', 2, 'Coding both conditions every time ''CP'' appears, regardless of context');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b25837a0-8686-4edc-b815-96f44ff48618', '99209422-ef8f-40b5-abd0-6501025dad4d', 3, 'Ignoring the abbreviation entirely and coding nothing related to it');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3438c652-8109-432c-a687-7c62e593e110', '6547bbeb-fb52-4a20-8059-cbb490cb127a', 0, 'Assuming ''N'' by default for any condition not mentioned in the admission note, without further review');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e5180d29-c5f1-4c6d-bc2e-dcdfb256991c', '6547bbeb-fb52-4a20-8059-cbb490cb127a', 1, 'Reviewing admission-time assessments (ED note, nursing admission assessment, H&P) to confirm the condition was genuinely absent or not yet clinically evident at the time of the inpatient admission order, consistent with the condition''s actual documented onset');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('56cd8d4e-50f3-4246-8d24-adfff9899564', '6547bbeb-fb52-4a20-8059-cbb490cb127a', 2, 'Relying solely on which day of the stay a diagnosis first appears on a problem list, without regard for actual clinical onset');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3da97d67-a1c7-487e-ade3-9488d682d98a', '6547bbeb-fb52-4a20-8059-cbb490cb127a', 3, 'Never validating POA once initially assigned by an encoder default');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3a6e35c0-6130-4a90-9053-270eebbb35d1', '31e0d10d-0e0d-4150-b981-894f8b3b7bb9', 0, 'Not a documentation concern, since resident documentation is always independently sufficient regardless of facility policy');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('920119d6-4be9-4346-a02f-0ada26eafb0b', '31e0d10d-0e0d-4150-b981-894f8b3b7bb9', 1, 'A completeness gap relative to the facility''s own authentication requirements, which should be identified and resolved (obtaining the required co-signature) as part of ensuring documentation meets applicable accreditation/organizational standards');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ddaf8c42-cc64-420a-9168-6a1d40d11860', '31e0d10d-0e0d-4150-b981-894f8b3b7bb9', 2, 'Something that automatically invalidates every diagnosis in the discharge summary for coding purposes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('644e7875-c921-40b0-924f-77ee69bf00e8', '31e0d10d-0e0d-4150-b981-894f8b3b7bb9', 3, 'Irrelevant to HIM/coding documentation-integrity review');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('309140ca-189b-488f-be8f-dad8d2033128', 'cc4a6ecf-0860-4279-ba86-de30880fbcd8', 0, 'A normal, unremarkable documentation pattern requiring no attention');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d9792e32-93e4-45f7-ae10-585079df4df6', 'cc4a6ecf-0860-4279-ba86-de30880fbcd8', 1, 'A potential documentation gap — objective clinical data suggesting a possible clinical event with no corresponding physician evaluation/assessment documented, which may represent either a genuine care gap or simply an undocumented assessment, and is worth flagging for review/query if it affects code assignment (e.g., possible undiagnosed sepsis)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('25afc587-8770-4d8e-968f-16ca911e5ab7', 'cc4a6ecf-0860-4279-ba86-de30880fbcd8', 2, 'Something that should be resolved by the nursing staff alone, with no coder or CDI involvement ever appropriate');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c0f44548-5f82-473a-985c-f6b8078934d2', 'cc4a6ecf-0860-4279-ba86-de30880fbcd8', 3, 'Proof that no further coding is needed for this admission');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2b679cdc-f13a-4965-b7de-9f896d313a17', '81389433-5120-4a16-bcbc-8c86a85e3c29', 0, 'Assuming the most commonly used device type by default when the operative report doesn''t specify');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d99b4775-4358-4acb-82e3-65d0c89eb685', '81389433-5120-4a16-bcbc-8c86a85e3c29', 1, 'Confirming the operative report, device log, or implant record explicitly documents the specific device type/characteristic needed to support the more specific code value, rather than guessing based on typical practice patterns');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('431cc0a2-4930-4d6b-8aa6-db05f69ae127', '81389433-5120-4a16-bcbc-8c86a85e3c29', 2, 'Ignoring device specificity entirely, since ICD-10-PCS device values are optional');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a712cffe-37fe-4765-8734-b3728122cca7', '81389433-5120-4a16-bcbc-8c86a85e3c29', 3, 'Relying solely on the supply/charge master entry without any clinical documentation cross-check');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('21e45f6f-49c5-4ae9-87a5-2ca71bdf289a', '5e4cd141-a975-48b5-8442-3125869eed82', 0, 'Assuming the finding was insignificant and dropping it from consideration entirely');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8b12830e-a485-435f-8f65-73dc83c8a366', '5e4cd141-a975-48b5-8442-3125869eed82', 1, 'Recognizing the note doesn''t actually resolve the clinical question, and reviewing further documentation (subsequent notes, discharge summary) or querying if the ambiguity affects code assignment for the current encounter, rather than assuming an outcome the note doesn''t actually state');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4f590831-daf3-41f4-8ee5-d5c6f78ae53c', '5e4cd141-a975-48b5-8442-3125869eed82', 2, 'Coding the finding as definitively resolved based on the positive tone of the note');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('21a06345-85c8-4e41-949d-6ca557fe2be1', '5e4cd141-a975-48b5-8442-3125869eed82', 3, 'Treating vague reassurance language as equivalent to an explicit clinical determination');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('32e30d4a-f26b-4254-9f96-015b4c1cccf0', '00b35e7c-84a3-4e58-8c74-e2ef05cab101', 0, 'Templated documentation should always be taken at face value with no critical review, since templates are pre-approved by the facility');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cbc16348-42f9-4cde-9cd2-b710aef26b00', '00b35e7c-84a3-4e58-8c74-e2ef05cab101', 1, 'Coders/CDI staff should be alert to templated or copy-forwarded documentation that may not accurately reflect the actual current encounter (e.g., an outdated finding carried forward unchanged across multiple notes), and should verify clinical accuracy/currency before relying on it for code assignment');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d079df23-4b42-4166-94b4-38f8d75fadc7', '00b35e7c-84a3-4e58-8c74-e2ef05cab101', 2, 'Templated documentation should never be used for coding under any circumstances, even when accurate');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('eec5b1af-8197-49cd-8495-d4595ab3763c', '00b35e7c-84a3-4e58-8c74-e2ef05cab101', 3, 'Only handwritten notes may ever be used to support code assignment');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2aadd34e-c77e-4342-bbec-fe0f3649dcca', 'b03790af-bb8c-44b4-9d21-83586f2cd87e', 0, 'Sufficient documentation to code diabetes automatically, since insulin was ordered and given');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5403d655-a14d-430e-a6ee-9c26d410972b', 'b03790af-bb8c-44b4-9d21-83586f2cd87e', 1, 'A documentation gap — treatment (insulin) is occurring without a corresponding documented diagnosis justifying it, which should prompt further chart review or a query to establish the actual diagnosis before a diabetes/hyperglycemia code is assigned');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d5d184d5-d740-4bbc-9f63-6aaf6ea4bfa3', 'b03790af-bb8c-44b4-9d21-83586f2cd87e', 2, 'Something that should simply be ignored since orders and nursing notes are sufficient on their own to establish any diagnosis');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b36f688b-c303-4047-bba4-90694f349e3c', 'b03790af-bb8c-44b4-9d21-83586f2cd87e', 3, 'Proof that the patient definitely has type 1 diabetes');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e5747ab4-9365-4d19-99ab-b1c896b98624', '18575f6c-16ea-4b53-a446-2e7b59fbf29c', 0, 'No special documentation practice is needed beyond standard operative reporting');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('883e33d2-9e51-46b5-a919-2f839d604e2d', '18575f6c-16ea-4b53-a446-2e7b59fbf29c', 1, 'Confirming the operative/implant documentation captures device-identifying information (e.g., serial/lot number, manufacturer) sufficient to support both accurate coding and any future recall-tracking/patient-safety needs');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a58a611a-aece-4775-9784-e04e759614ab', '18575f6c-16ea-4b53-a446-2e7b59fbf29c', 2, 'Device identification documentation is solely a supply-chain/materials-management concern with zero coding relevance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b3cc0261-4153-4d14-aa3c-7ebbb8b206c1', '18575f6c-16ea-4b53-a446-2e7b59fbf29c', 3, 'Device serial numbers are never relevant to ICD-10-PCS device-value specificity');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a9e636d6-98a4-4685-afcf-f0fdc3bd8923', 'c04081ed-56a0-49dd-8966-2cdc77a9b13b', 0, 'Ignored, since admission date/time never affects UHDDS abstraction accuracy');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('802baec9-efaa-4d8f-9e2c-7aee36ba1de7', 'c04081ed-56a0-49dd-8966-2cdc77a9b13b', 1, 'Reconciled to the clinically/legally correct admission date/time (typically the physician''s admission order timestamp) before finalizing abstracted UHDDS data, since a systems-interface artifact shouldn''t be allowed to misstate a core UHDDS data element');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d4544aff-8e7c-4e41-92ad-cb5b0a08882b', 'c04081ed-56a0-49dd-8966-2cdc77a9b13b', 2, 'Reported using whichever date is earlier, regardless of clinical accuracy');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d70d12e9-0aa3-490c-9f84-fbd2666b7e0e', 'c04081ed-56a0-49dd-8966-2cdc77a9b13b', 3, 'Resolved only if it affects reimbursement, otherwise left inconsistent');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('32e9cb53-0aba-4c6f-baaf-573624f563d4', '3e28ae55-3f2c-401b-b84e-e64bfc50b7e4', 0, 'Depth is coding-irrelevant; all debridements are coded identically regardless of depth');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c860ee09-47ec-4137-872c-902f6b1b6a4f', '3e28ae55-3f2c-401b-b84e-e64bfc50b7e4', 1, 'The operative/procedure note must document the actual depth of tissue debrided, since ICD-10-PCS (and CPT, in the outpatient/physician setting) code selection for debridement is directly dependent on documented depth — assuming depth based on the reason for debridement is not an acceptable substitute for explicit documentation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e2aa9e64-b901-4028-b766-492ad89d185c', '3e28ae55-3f2c-401b-b84e-e64bfc50b7e4', 2, 'Depth is assumed to always be ''skin only'' unless a query is submitted for every single case');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('676562c6-8be7-4aba-8a13-f2d219da263c', '3e28ae55-3f2c-401b-b84e-e64bfc50b7e4', 3, 'Only the total surface area matters; depth is never a coding factor');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('29f821d6-89b5-4421-bcdb-8953edd6577d', 'a68bd7a4-457f-4828-b60d-4fd4d29d03cd', 0, 'Rely solely on the supply/implant log without any further clinical documentation review, treating it as fully equivalent to physician documentation of procedure extent');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a7979cca-3978-4d04-92dc-db60df7ba9c2', 'a68bd7a4-457f-4828-b60d-4fd4d29d03cd', 1, 'Recognize that supply documentation alone is generally not an adequate substitute for the physician''s own operative documentation of procedure extent — review the full operative note further and/or query the surgeon to explicitly confirm total vs. partial replacement before finalizing the procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('648fa1d6-7c79-4664-bb14-68db19e77043', 'a68bd7a4-457f-4828-b60d-4fd4d29d03cd', 2, 'Assume total replacement by default since it''s more common');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c4952984-ccd1-4349-ad9a-30cc6516f5ac', 'a68bd7a4-457f-4828-b60d-4fd4d29d03cd', 3, 'Code both total and partial replacement to cover both possibilities');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3b3f279a-7700-40f7-82ab-fd0b465dc571', 'c779640e-1ef2-401f-bb0b-159278d55d62', 0, 'No concern exists; physical exam findings never change day to day');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fb07bb2a-7e4f-46b9-8c5f-9472fef0937c', 'c779640e-1ef2-401f-bb0b-159278d55d62', 1, 'It risks the record inaccurately representing the patient''s CURRENT clinical status on the date of that note, which can mislead both ongoing clinical care and coding/abstraction relying on that note''s documented findings for that specific date');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e03e3885-47a8-4459-8fa8-608ef93dcae7', 'c779640e-1ef2-401f-bb0b-159278d55d62', 2, 'It is always beneficial and should be encouraged as a documentation efficiency practice with no downside');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4c62f47a-49c1-4ce3-a223-eb5c76ac92f6', 'c779640e-1ef2-401f-bb0b-159278d55d62', 3, 'It only matters for outpatient encounters, never inpatient');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6351550e-7a04-4db5-955c-a027ebb55e26', '28c06f8b-2c9d-48e7-88c5-cdaf52ac2d5f', 0, 'No action; discharge summaries always take precedence over any other note automatically, without exception');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b49d673c-832b-46f2-8b8f-59776fa8d6bb', '28c06f8b-2c9d-48e7-88c5-cdaf52ac2d5f', 1, 'Careful review of the full record around the time of discharge to determine which reflects the patient''s actual condition/status, since discharge condition characterization can be clinically meaningful and inconsistent with a more detailed contemporaneous note');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('16dbcb83-601e-45fc-b631-527ec8703c86', '28c06f8b-2c9d-48e7-88c5-cdaf52ac2d5f', 2, 'Assuming the progress note is simply outdated and irrelevant by definition');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fc0fb261-435e-4c77-b335-7d83f77a0453', '28c06f8b-2c9d-48e7-88c5-cdaf52ac2d5f', 3, 'Automatically querying the physician without first reviewing all available documentation around the discharge date');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8f8d704b-7df5-4547-9872-2da2a338e395', 'd160f7c5-0aba-487e-8857-bcfb5328ffc4', 0, 'Any adverse event occurring anywhere near the time of anesthesia administration may automatically be coded as an anesthesia complication');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bc833b79-0650-4355-a0a8-698f28f052fd', 'd160f7c5-0aba-487e-8857-bcfb5328ffc4', 1, 'The provider must document a condition specifically attributable to the anesthesia itself (not simply a coincidental or expected/anticipated effect), consistent with the general rule that complications require explicit provider-established causal documentation, not coder inference from proximity in time');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f76e58a9-cc56-4dcb-a189-f7724fdd2384', 'd160f7c5-0aba-487e-8857-bcfb5328ffc4', 2, 'Anesthesia complications can never be coded under any circumstances');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('79a7c9d6-f72f-4770-9188-44d62580fb28', 'd160f7c5-0aba-487e-8857-bcfb5328ffc4', 3, 'The anesthesiologist''s mere presence in the operating room automatically supports coding a complication regardless of documentation');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b51b004c-c2cf-4472-98db-9ad190539a8b', '8473115e-54ab-4fc4-a4be-dfb848cc1bfb', 0, 'Automatically including every problem-list entry regardless of relevance to the current encounter');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0d7f7b57-7c91-4287-90e4-a1b5d7404d07', '8473115e-54ab-4fc4-a4be-dfb848cc1bfb', 1, 'Whether the condition meets the applicable additional-diagnosis reporting criteria for THIS encounter specifically (clinical evaluation, treatment, monitoring, or impact on care during this visit) — a static problem-list entry alone, without current-encounter relevance, doesn''t automatically qualify');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ac8c056d-9de6-426a-9e96-08962ff23208', '8473115e-54ab-4fc4-a4be-dfb848cc1bfb', 2, 'Never reporting any chronic condition once it has been reported once previously');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('aa6c4490-dc59-4705-93eb-bdbba765bcd5', '8473115e-54ab-4fc4-a4be-dfb848cc1bfb', 3, 'Whichever choice increases the encounter''s reimbursement, regardless of documentation');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0f68e712-42f7-476a-afcc-ad2fcfa58a05', '01d95159-35f8-4145-ad1b-dcd48f3fe3e8', 0, 'Any transfusion given during a stay automatically supports coding a transfusion reaction, whether or not one is documented');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8e916602-ac65-44ab-8c16-1e5fe0415faa', '01d95159-35f8-4145-ad1b-dcd48f3fe3e8', 1, 'A transfusion reaction must be clinically documented by the provider as an actual adverse reaction (with clinical findings/assessment), not assumed simply because a transfusion occurred during the stay');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('84c395ae-b5f1-4e66-93a1-915cff54f978', '01d95159-35f8-4145-ad1b-dcd48f3fe3e8', 2, 'Transfusion reactions can never be coded as a complication under any circumstance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9701f7e2-fc9e-4351-a12c-08a7e1bb21eb', '01d95159-35f8-4145-ad1b-dcd48f3fe3e8', 3, 'Nursing transfusion monitoring flowsheets alone, with no physician documentation of a reaction, are sufficient by themselves to support a diagnosis code');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e5a607aa-eff8-4e5f-a4ea-38bf85245340', '62c14974-de7b-4259-a02e-7d7ccae558f6', 0, 'A single option representing the CDI specialist''s suspected diagnosis, worded so the physician need only sign');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1744fc25-214b-41e9-a0a2-c71f5ef8fe08', '62c14974-de7b-4259-a02e-7d7ccae558f6', 1, 'Multiple clinically plausible etiologies (e.g., prerenal, intrinsic/ATN, postrenal, another specified cause) plus an ''other'' or ''clinically undetermined'' option, allowing the physician to exercise independent clinical judgment');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9108dcd4-05cc-4c19-95da-403579dace14', '62c14974-de7b-4259-a02e-7d7ccae558f6', 2, 'Only ''yes'' or ''no'' regarding a single suspected diagnosis');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8b1cc8d2-f623-4ee0-ba38-0ff0ff384b21', '62c14974-de7b-4259-a02e-7d7ccae558f6', 3, 'No answer options — physicians must always write a fully free-text response with no structure provided');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bf5af60b-81e7-42f2-ae96-f404b9b1eddd', '5320e6b9-2a8d-4da4-baef-076f658f5fe2', 0, 'Always prohibited under any circumstance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('85e65488-54f5-4c9d-914c-7f63b14403b9', '5320e6b9-2a8d-4da4-baef-076f658f5fe2', 1, 'Generally acceptable and often good practice when used to objectively present the clinical picture supporting why clarification is being sought, as long as the query remains non-leading and doesn''t presuppose the diagnosis');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2d465a2b-2a07-4b96-9725-a338909491cc', '5320e6b9-2a8d-4da4-baef-076f658f5fe2', 2, 'Only acceptable if the physician has never heard of the criteria before');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3e94aa18-e666-4756-be83-9cb10fbc90b7', '5320e6b9-2a8d-4da4-baef-076f658f5fe2', 3, 'Required to be omitted from every query regardless of clinical relevance');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('21097e2c-7f70-4d52-bbaf-d0316cff28fa', '025108f0-85ca-4c88-8c3a-fb7a64717945', 0, 'Ignore the response and code based on the coder''s own best guess anyway');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('12f772b0-cdcd-4dac-a449-11cb8cd706b5', '025108f0-85ca-4c88-8c3a-fb7a64717945', 1, 'Respect the provider''s documented clinical judgment — if the etiology genuinely cannot be determined, code to the level of specificity actually supported (e.g., the abnormal finding itself or an unspecified code), rather than overriding the provider''s answer');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e54811cb-6688-4197-b2dd-3e397a33d9c1', '025108f0-85ca-4c88-8c3a-fb7a64717945', 2, 'Resubmit the same query repeatedly until a specific diagnosis is given');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('232189a2-c76e-4918-a36a-e3e7883a10a3', '025108f0-85ca-4c88-8c3a-fb7a64717945', 3, 'Automatically default to the most severe possible diagnosis when a provider states it cannot be determined');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cee916be-6df5-42ce-9857-dd1324861f11', 'fe2ce522-17ba-4000-ac26-8abfbea7aa5f', 0, 'When clinical indicators in the record clearly support a more specific or additional diagnosis that isn''t yet documented');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6980c6c4-580b-46e8-a533-eee146aed3dd', 'fe2ce522-17ba-4000-ac26-8abfbea7aa5f', 1, 'When the documentation is already clear, complete, and consistent, and a query would serve only to fish for a higher-weighted diagnosis unsupported by the actual clinical picture');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3cae6350-a84f-496c-92c0-d0eace05e597', 'fe2ce522-17ba-4000-ac26-8abfbea7aa5f', 2, 'When POA status for a significant condition is genuinely ambiguous from the available documentation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e9b62abe-e03a-42ec-a410-d36865bea560', 'fe2ce522-17ba-4000-ac26-8abfbea7aa5f', 3, 'When conflicting documentation about a clinically significant fact exists in the record');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('21475ee8-fb21-4684-a9af-85dd73c870f9', '48110d91-3c68-4385-bd72-b6c4f4885aa3', 0, 'Leading, because it lists only one specific diagnosis');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d07ba8dc-1b09-42f6-80fd-2007ef129330', '48110d91-3c68-4385-bd72-b6c4f4885aa3', 1, 'Non-leading, because it presents objective clinical indicators (lab trend, transfusion) and offers multiple genuine response options, including ''not clinically significant,'' without presupposing the answer');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('556c3e37-ef0e-4cc8-ad2a-1a5d18092662', '48110d91-3c68-4385-bd72-b6c4f4885aa3', 2, 'Non-compliant because it references lab values at all');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e9268279-5c7b-4593-ab30-2400e74d8d98', '48110d91-3c68-4385-bd72-b6c4f4885aa3', 3, 'Leading because it mentions a transfusion');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1e6ac921-7258-4a04-b4e8-95399dd87cd0', '6eb2eb70-d4c3-43b6-9317-c951be4f49f3', 0, 'Comply and code sepsis based solely on the verbal instruction, with no documentation update');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('925699ff-9f34-42e1-9e63-67f350ec0ddd', '6eb2eb70-d4c3-43b6-9317-c951be4f49f3', 1, 'Explain that coding requires supporting documentation in the health record itself, and request that the clarification be documented (even briefly) in the record or via a formal, compliant query response, since verbal instructions alone don''t create an auditable, codeable record');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4d5485ad-5ecf-4328-9df0-f17127a81b78', '6eb2eb70-d4c3-43b6-9317-c951be4f49f3', 2, 'Report the physician to the medical board immediately with no further discussion');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b4169e40-db08-429f-b668-430a570434cd', '6eb2eb70-d4c3-43b6-9317-c951be4f49f3', 3, 'Code sepsis and note only in a personal file that the physician said so verbally');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('37aaa87d-4030-48e1-a9fb-849caad6e01f', 'ee25110e-8a90-42c3-82c6-bc6aec993955', 0, 'Presenting relevant clinical indicators supporting the query');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('838b2b76-1b6c-4a18-8047-af12ee53e547', 'ee25110e-8a90-42c3-82c6-bc6aec993955', 1, 'Providing multiple clinically reasonable answer choices');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('11347af2-bc56-4eab-a2c0-36d52f31ab21', 'ee25110e-8a90-42c3-82c6-bc6aec993955', 2, 'Embedding the desired answer within the question stem itself in a way that all but tells the provider what to write');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('92add65e-e8cc-4a2e-9da6-db33e167a945', 'ee25110e-8a90-42c3-82c6-bc6aec993955', 3, 'Including an ''other, please specify'' option');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bd2e8ab3-4839-44c4-8788-773eb15525c5', 'c1c675ae-e32a-4696-8008-6eba75bbd98d', 0, 'Code malnutrition anyway based on the dietitian''s assessment alone');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a0e62b2a-fb88-49cf-ae2c-71e8c0f8a220', 'c1c675ae-e32a-4696-8008-6eba75bbd98d', 1, 'Recognize this as a genuine query opportunity — construct a compliant, non-leading query to the physician presenting the objective clinical indicators and asking them to determine/confirm a diagnosis (if any) and its severity');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b16926e6-cedc-4b0c-b2be-4c0cbb198597', 'c1c675ae-e32a-4696-8008-6eba75bbd98d', 2, 'Ignore the indicators since only physicians ever look at labs');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b3dd707f-fd57-40fb-9b2d-ecebf3b26695', 'c1c675ae-e32a-4696-8008-6eba75bbd98d', 3, 'Automatically assume the most severe malnutrition code is warranted');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('238eb9f7-54ec-4176-84ac-0b5dfca07667', '9df83ec6-84e9-41c5-b441-9360cc56f4a3', 0, 'Always hold every claim indefinitely with no query-response timeframe policy ever applied');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('84216762-8498-4d6a-9afb-e4759e87282a', '9df83ec6-84e9-41c5-b441-9360cc56f4a3', 1, 'Follow the organization''s query-escalation and timeliness policy (e.g., escalation to a physician advisor, or coding to the best-supported level of specificity if a response genuinely isn''t obtainable in time), rather than either indefinitely holding every claim or fabricating a response');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ba1c36dc-9950-4c96-bb51-fce1966517a7', '9df83ec6-84e9-41c5-b441-9360cc56f4a3', 2, 'Assume the most favorable answer on the provider''s behalf without any response');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5b2516aa-ddd5-4b06-8da0-2b9d791bf147', '9df83ec6-84e9-41c5-b441-9360cc56f4a3', 3, 'Cancel the claim entirely with no further coding action');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('baf0b6f1-0143-405f-a0bc-f3e8dc1ce2ec', '0d69dcba-f2b5-49cf-8017-2ac58665bec5', 0, 'To pressure physicians into always agreeing with suggested diagnoses');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9b583179-1ff6-47ad-af50-8c6ef5a0ac67', '0d69dcba-f2b5-49cf-8017-2ac58665bec5', 1, 'To identify patterns (e.g., unusually high agreement rates with specific CC/MCC-related queries, or low overall physician response rates) that may warrant further review of query construction quality or physician engagement, supporting both compliance oversight and program effectiveness');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b93fb34b-345e-4d12-87dd-c9d6ac0720c5', '0d69dcba-f2b5-49cf-8017-2ac58665bec5', 2, 'Query metrics have no legitimate compliance or quality purpose');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('11b9623e-3ba3-45a2-86e9-84f5617a43d2', '0d69dcba-f2b5-49cf-8017-2ac58665bec5', 3, 'To determine individual physician compensation directly');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f2dc70de-4a47-46aa-b488-f6feac2a4598', 'bdfdf08c-14f5-4c56-9bc5-544733be2f80', 0, 'An internal facility self-audit with no external party involved');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9b2340b6-335c-4707-b4f4-17a03a7de5ec', 'bdfdf08c-14f5-4c56-9bc5-544733be2f80', 1, 'A CMS program using contracted auditors to identify improper Medicare payments (both overpayments and underpayments), including coding-related errors, for post-payment (and in some cases prepayment) review');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('435f53c0-b0a8-42b1-9aae-555e9be2cece', 'bdfdf08c-14f5-4c56-9bc5-544733be2f80', 2, 'A one-time historical program that no longer has any relevance to current compliance practice');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8505375e-5aa5-4111-9ead-efd32e776e4e', 'bdfdf08c-14f5-4c56-9bc5-544733be2f80', 3, 'A program that reviews only physician credentialing, not coding accuracy');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6a7e6d3a-0c4b-4e28-a441-ecd72a9bbab9', '59337d79-28f2-4749-a3dc-c7d13507c5cb', 0, 'Individual physician licensing decisions only');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e908ad74-b712-4b79-bc40-bfbaab16a7a9', '59337d79-28f2-4749-a3dc-c7d13507c5cb', 1, 'Hospital-level quality reporting and value-based payment program purposes, incentivizing reduction of preventable inpatient complications');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('89385052-41d7-4f7c-a769-9a7a3dc1d677', '59337d79-28f2-4749-a3dc-c7d13507c5cb', 2, 'Determining patient copayment amounts directly');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2ddc4a97-211c-4f2b-9c79-5754d6a570d0', '59337d79-28f2-4749-a3dc-c7d13507c5cb', 3, 'Replacing MS-DRG assignment entirely');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3293f119-ff1f-4e96-ab2f-a78bad7be48d', '249bf297-3535-4218-a782-6108e057857d', 0, 'POA indicators have no bearing on PSI/HAC calculations');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('59794259-41c8-4c2b-a319-068ad712f652', '249bf297-3535-4218-a782-6108e057857d', 1, 'PSI/HAC logic relies heavily on POA indicators to distinguish conditions present before admission (not attributable to the current hospitalization) from those that developed during the stay (potentially reportable as a HAC or contributing to a PSI flag) — inaccurate POA assignment can directly misstate quality/safety metrics and associated payment');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('248a9f05-6dd7-47b6-88f4-5eb7c2c082ad', '249bf297-3535-4218-a782-6108e057857d', 2, 'POA indicators only matter for outpatient claims, which don''t use PSI/HAC logic at all');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('02524015-f0a1-4475-9161-6c87d9de856c', '249bf297-3535-4218-a782-6108e057857d', 3, 'PSI/HAC measures apply only to psychiatric facilities');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5e6d8655-c11f-4db8-8bdd-9d0d2a0bc360', '26310805-83cc-4725-8605-7275e7bb7509', 0, 'Ignoring OIG Work Plan publications entirely, since they aren''t legally binding rules');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7c5d24d2-8fc1-44d6-96fb-2a64b799da28', '26310805-83cc-4725-8605-7275e7bb7509', 1, 'Reviewing the facility''s own coding/billing practices related to the flagged area proactively, as part of ongoing compliance monitoring, since OIG Work Plan items signal areas of anticipated federal audit focus');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('aeacb354-62b8-4b15-ae00-20017725b1f3', '26310805-83cc-4725-8605-7275e7bb7509', 2, 'Immediately stopping all billing for that DRG indefinitely');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0fd0159b-b1b8-479f-b73d-fba805bc6279', '26310805-83cc-4725-8605-7275e7bb7509', 3, 'Assuming the facility is automatically exempt if it has never been audited before');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1bbcd536-6b7d-4887-b753-48c942f8a9f9', '90e07fb3-37de-43e7-b8d9-7688bc850bbc', 0, 'Alter the documented diagnosis to one that doesn''t require prior authorization, regardless of clinical accuracy, to avoid a denial');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e9ccbdf1-71c1-4cf6-b57b-7d062f47ac45', '90e07fb3-37de-43e7-b8d9-7688bc850bbc', 1, 'Code the encounter accurately based on the actual documentation regardless of authorization status — prior authorization is a payer administrative/coverage requirement addressed through the billing/authorization workflow, not something that should influence the accuracy of the clinical code assignment itself');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5e6dbf5f-96ed-45c2-bdc0-3c9b39351a8a', '90e07fb3-37de-43e7-b8d9-7688bc850bbc', 2, 'Refuse to code the encounter at all');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('73f9570b-1819-439f-971c-3a95d4e593c0', '90e07fb3-37de-43e7-b8d9-7688bc850bbc', 3, 'Assign whichever code the payer is most likely to approve, regardless of documentation');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f80f3d35-c858-4676-a760-9b86bf7bd636', '91c8a4e6-c0e6-482a-906c-04eec14b5520', 0, 'A state-level licensing exam for coders');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8100ad7e-314b-4d7b-bf67-0cd11742cb2f', '91c8a4e6-c0e6-482a-906c-04eec14b5520', 1, 'A CMS program that measures improper payment rates in the Medicare Fee-for-Service program by reviewing a statistically valid random sample of claims, including for coding/documentation-supported errors');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5e92f696-7552-4c75-a98a-aaa5080e11e9', '91c8a4e6-c0e6-482a-906c-04eec14b5520', 2, 'A private-payer-only initiative with no federal component');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e7db06fb-361c-49eb-b6ea-cc1bb3236e2a', '91c8a4e6-c0e6-482a-906c-04eec14b5520', 3, 'A one-time audit that occurred only in the program''s founding year and never again');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('85bd7aa5-0d9a-4d6a-9a3e-e9d3709a8f69', 'c7a06b1c-e659-4062-a07e-baebb36367c1', 0, 'Processing and reviewing Medicare Part A/B claims for a defined jurisdiction, including issuing Local Coverage Determinations (LCDs) that affect medical necessity coding edits');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5f18ba43-740f-4707-9733-8c151dfe213b', 'c7a06b1c-e659-4062-a07e-baebb36367c1', 1, 'Setting federal law regarding HIPAA');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('47cedbe8-a5fa-4217-9140-e5ad2a8e130e', 'c7a06b1c-e659-4062-a07e-baebb36367c1', 2, 'Licensing individual coders nationally');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c4ffe024-a94d-4e63-836b-bae3f137f218', 'c7a06b1c-e659-4062-a07e-baebb36367c1', 3, 'Operating hospital EHR systems directly');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1d7880ac-8931-4822-ad42-7ba9f61829c4', '631af4db-bae4-447d-b98c-be456b7f63ef', 0, 'NCDs are issued by CMS nationally and apply across all Medicare jurisdictions, while LCDs are issued by individual MACs and apply only within their specific jurisdiction');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('188c57c9-818f-4768-a813-a49e92ea04e4', '631af4db-bae4-447d-b98c-be456b7f63ef', 1, 'LCDs always override NCDs when the two conflict');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('394eaf70-8b2a-4f76-ae61-71347b95beb8', '631af4db-bae4-447d-b98c-be456b7f63ef', 2, 'NCDs apply only to Medicaid, never Medicare');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e1acb6dc-6ded-4762-bff2-5d7dd7b6b743', '631af4db-bae4-447d-b98c-be456b7f63ef', 3, 'There is no real distinction; the terms are interchangeable');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('acbc0fd0-4868-44dd-9a13-1d5fe29195e5', 'e0eeaef8-962f-4a13-b78a-e33a81b5c2b1', 0, 'Say nothing and continue coding as before, since it isn''t the coder''s job to flag system issues');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('75eccb1b-5d54-42c3-a41b-e8ac7cc8e277', 'e0eeaef8-962f-4a13-b78a-e33a81b5c2b1', 1, 'Escalate the finding through the organization''s compliance reporting channel promptly, since a systemic, ongoing error pattern (regardless of how it was discovered) is exactly the kind of issue a compliance program is designed to catch and correct, including potential claim correction/self-disclosure obligations');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('88d97356-0d15-43da-82fe-9d5b78716123', 'e0eeaef8-962f-4a13-b78a-e33a81b5c2b1', 2, 'Quietly fix future claims without informing anyone about the historical pattern');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('109b04c8-69dd-43b1-af63-c91028cae139', 'e0eeaef8-962f-4a13-b78a-e33a81b5c2b1', 3, 'Wait for the next scheduled external audit to raise it');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('332e1133-d453-41cc-a4cb-c44c26ec1074', 'c13d93da-d52f-45af-9403-2eb89f3dc8be', 0, 'Providers have no obligation to report or return identified Medicare/Medicaid overpayments');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c1e4db5f-4824-490f-9542-39d402695948', 'c13d93da-d52f-45af-9403-2eb89f3dc8be', 1, 'Providers to report and return an identified overpayment within 60 days of identification (or the date a corresponding cost report is due, if applicable), or risk False Claims Act exposure for retaining a known overpayment');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ae1e56ca-df87-4375-b22b-ca6a76a07b69', 'c13d93da-d52f-45af-9403-2eb89f3dc8be', 2, 'A 60-day grace period before any coding error must even be investigated');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c7bda229-242b-47df-a4b8-abe241d1b3f7', 'c13d93da-d52f-45af-9403-2eb89f3dc8be', 3, 'The rule applies only to overpayments exceeding $1 million');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c40bd8f9-83a6-46e4-a6f0-1e5926392bca', '202f579f-1050-4674-9689-f243b31d548d', 0, 'Reporting a single comprehensive code for a group of services that are correctly bundled together');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d1172d9b-a3de-4390-a73b-283a6a6c757b', '202f579f-1050-4674-9689-f243b31d548d', 1, 'Separately reporting the individual component codes of a procedure that should be reported using a single, more comprehensive code, resulting in inflated reimbursement — the pattern NCCI Procedure-to-Procedure edits are specifically designed to catch');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('dc152445-496c-41ce-ba11-37755c915e31', '202f579f-1050-4674-9689-f243b31d548d', 2, 'A legitimate and encouraged coding practice with no compliance implications');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9cb464c6-9709-407f-9ddf-e0f7c35d040f', '202f579f-1050-4674-9689-f243b31d548d', 3, 'Something that applies only to inpatient DRG coding, never outpatient/professional coding');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('15c61e49-bece-4fdd-875a-503ea74f691d', 'e5a5f79c-fb2a-4022-bc1c-ff78c6c9e81d', 0, 'Productivity targets always override documentation-accuracy obligations');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('272dcb64-0d3f-474a-bdd0-32c0da8bf68c', 'e5a5f79c-fb2a-4022-bc1c-ff78c6c9e81d', 1, 'Coding accuracy/compliance obligations do not yield to internal productivity pressure — a coder should raise concerns about unrealistic quotas through appropriate channels rather than compromise on documentation-supported accuracy');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0b1cb269-bb3d-4e18-8367-b66095b36d8e', 'e5a5f79c-fb2a-4022-bc1c-ff78c6c9e81d', 2, 'It''s acceptable to guess as long as the guess is later corrected if caught');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e0eeaeca-9cc9-44f3-a196-fa44696e07ba', 'e5a5f79c-fb2a-4022-bc1c-ff78c6c9e81d', 3, 'Only management, never the individual coder, bears any responsibility for guessed codes');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4a369ca5-1ad3-405b-9ce8-9fb70d3c3940', 'f5b833fa-f26c-4552-8c8c-66ce57458bd5', 0, 'Blaming the individual coder involved with no further investigation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e79987e5-e037-4b5b-a4bb-958bf4816f2f', 'f5b833fa-f26c-4552-8c8c-66ce57458bd5', 1, 'Examining contributing factors broadly — documentation quality, training gaps, system/encoder configuration, workflow pressures — not just the individual coder''s specific action, to prevent recurrence systemically');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0f975c36-7bdf-45aa-8ab3-5617edc666a9', 'f5b833fa-f26c-4552-8c8c-66ce57458bd5', 2, 'Concluding the analysis the moment the involved coder is identified, regardless of other contributing factors');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bcc94a06-c40b-4b39-9b12-7311b806347f', 'f5b833fa-f26c-4552-8c8c-66ce57458bd5', 3, 'Skipping root-cause analysis entirely once the specific claim is corrected');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f958d944-1cde-4885-bbd7-56bf38ca297b', '744263ab-7d7b-4ebb-b6b7-3a6524328bdf', 0, 'Risk analysis requirements apply only to IT departments, never to HIM/coding operations that access ePHI');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('edde07d9-d1fa-47b5-bbc3-291a37efae7b', '744263ab-7d7b-4ebb-b6b7-3a6524328bdf', 1, 'Any system or workflow through which coding staff access ePHI (encoders, CAC, abstracting systems, remote access arrangements) falls within the scope of the organization''s required, ongoing HIPAA Security Rule risk analysis');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9b9b1e2c-5299-4ba5-a128-216c6dadcbb3', '744263ab-7d7b-4ebb-b6b7-3a6524328bdf', 2, 'Risk analysis is a one-time requirement satisfied at system go-live, needing no periodic reassessment');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ab975441-dd31-4cfd-8da5-5e5be217b9d8', '744263ab-7d7b-4ebb-b6b7-3a6524328bdf', 3, 'Risk analysis applies only to systems storing Social Security numbers');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1dd3deb7-70cd-4a22-a6f0-a9a0eff74613', '21af6c6c-edfb-4bda-8473-eb8a2999c6e3', 0, 'No additional safeguards are needed for remote coding work versus on-site work');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9dcf8e8e-753b-43d7-b1b8-904d45bcb83b', '21af6c6c-edfb-4bda-8473-eb8a2999c6e3', 1, 'Appropriate technical and administrative safeguards (e.g., VPN/encrypted connections, multi-factor authentication, workstation security policies, prohibitions on printing/storing PHI locally) should be applied specifically to remote access scenarios, consistent with the Security Rule''s risk-based safeguard requirements');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('912febb5-9751-47cc-bc25-a053c269a673', '21af6c6c-edfb-4bda-8473-eb8a2999c6e3', 2, 'Remote coding work is prohibited under HIPAA in all circumstances');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('53b4c725-4c7b-4b54-89cc-d9400ea31c9c', '21af6c6c-edfb-4bda-8473-eb8a2999c6e3', 3, 'Only physical safeguards matter for remote work; technical safeguards are irrelevant');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('da7b0c0f-b86f-42a6-81ac-2f9b763f0a0c', '5a6be920-9ef9-4d02-b174-9b5132093ae3', 0, 'Generate unnecessary administrative burden with no real compliance value');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c6fdda7b-c283-45f8-a343-e9bc727a11f3', '5a6be920-9ef9-4d02-b174-9b5132093ae3', 1, 'Help ensure coders maintain current knowledge of evolving code sets, guidelines, and regulatory requirements over time, since coding rules and payer policy are not static');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('47d50780-683e-43cd-a2f9-e1a1b108531b', '5a6be920-9ef9-4d02-b174-9b5132093ae3', 2, 'Replace the CCS credential entirely with a facility-specific certificate');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('220c9527-56d2-4731-bfbc-fb5b819881e0', '5a6be920-9ef9-4d02-b174-9b5132093ae3', 3, 'Apply only to newly hired coders, never established staff');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a5064c0b-1ba3-4740-9435-b5692df871d3', '35691a69-f607-467c-b699-ec0668f13fa1', 0, 'It is automatically proof of fraud requiring immediate self-reporting with no further analysis');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('94fff15e-3f4e-4d94-9951-13d4724e5192', '35691a69-f607-467c-b699-ec0668f13fa1', 1, 'It is a data pattern that may warrant internal review (documentation quality, CDI/query practices, coding accuracy) to confirm the higher rate is clinically/documentation-supported rather than assuming either fraud or celebrating it as pure coding excellence without verification');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ffe75174-fa84-437f-b3cf-ac5f2cfdacd4', '35691a69-f607-467c-b699-ec0668f13fa1', 2, 'It has no compliance relevance since CC/MCC capture is purely a coding technicality');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d6d8ff9b-9b62-4a67-9ddf-0c58efbf3bf1', '35691a69-f607-467c-b699-ec0668f13fa1', 3, 'It should be ignored unless a payer specifically flags it');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5e414958-72fb-4436-9fac-f35f600aceaa', 'f1b41028-7dd6-4375-a4dd-25e8a99dcba7', 0, 'The two principles are identical in practice and always point to the same code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7e853802-8893-41f4-8708-2396f614f03d', 'f1b41028-7dd6-4375-a4dd-25e8a99dcba7', 1, 'Coding should be driven by what the documentation actually, accurately supports clinically — a higher-reimbursing code that isn''t supported by the documentation is not a compliant choice, even if a similar-sounding, less specific code would also technically be usable');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1297b3da-a579-44c1-b306-022a75743aff', 'f1b41028-7dd6-4375-a4dd-25e8a99dcba7', 2, 'Reimbursement potential should always be the deciding factor between two codes both technically supportable by documentation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8556cf20-1787-4684-9e5b-963dea9a5e2e', 'f1b41028-7dd6-4375-a4dd-25e8a99dcba7', 3, 'Specificity and reimbursement are unrelated concepts with no practical interaction');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('92d1b869-43cc-41b7-ad8b-03fcfa8d9773', '3b7132b7-d546-4062-a5cb-ab5ba1a1244a', 0, 'Only ICD-10-CM/PCS code updates, with no other content');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('106e5af9-610c-4a4f-b774-202fe7774475', '3b7132b7-d546-4062-a5cb-ab5ba1a1244a', 1, 'Code set updates, AHIMA''s Standards of Ethical Coding, applicable federal fraud/abuse laws (e.g., False Claims Act), HIPAA privacy/security obligations, and organization-specific policies (query practice, documentation standards)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('44bebb9c-9491-4374-a61f-c07a59a59ace', '3b7132b7-d546-4062-a5cb-ab5ba1a1244a', 2, 'Only HIPAA privacy training, since coding accuracy is covered elsewhere');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('db796e94-722d-421c-9aa5-a62322accb4b', '3b7132b7-d546-4062-a5cb-ab5ba1a1244a', 3, 'Only new-hire orientation, with no ongoing/refresher component');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0de2c904-213c-4411-b486-81ab54857446', '21064cb9-66dc-456a-8a95-a7736081718e', 0, 'No separation is necessary or beneficial; the same staff should ideally do both for efficiency');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ce85d99b-99b5-48c0-94b3-b09d5dfa56cc', '21064cb9-66dc-456a-8a95-a7736081718e', 1, 'Separating clinical/coding-accuracy functions from reimbursement-negotiation functions helps reduce the risk (and appearance) that coding decisions are influenced by reimbursement optimization rather than documentation-supported clinical accuracy');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4746c778-294f-43a0-9fcb-e5473c265d6d', '21064cb9-66dc-456a-8a95-a7736081718e', 2, 'Separation of duties is a concept that applies only to financial accounting, never to HIM/coding operations');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('eb425b43-e59b-487b-9e72-0bb6cc595850', '21064cb9-66dc-456a-8a95-a7736081718e', 3, 'This separation is required only for publicly traded healthcare companies');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8f7228c9-72de-4842-aed2-f659cf319c57', 'ef3d2827-ab1c-43c4-ba71-59f7079e9962', 0, 'A single hospital''s internal-only record storage with no external sharing capability');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3b04747e-95f9-43f1-95aa-3bbc15cf1947', 'ef3d2827-ab1c-43c4-ba71-59f7079e9962', 1, 'The electronic sharing of health-related information among different, often unaffiliated, organizations according to nationally recognized interoperability standards');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('80052df8-6cac-4dd2-955c-e2f2c403cd16', 'ef3d2827-ab1c-43c4-ba71-59f7079e9962', 2, 'Only billing data exchange between a hospital and a single payer');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c5d270e1-f5d5-4537-aa9c-d928d6c58686', 'ef3d2827-ab1c-43c4-ba71-59f7079e9962', 3, 'Replacing the need for any EHR system');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8bebe47f-e43f-48b5-8f8a-631a2280317d', '40ac3387-e23d-49c5-8cc3-737a66a97053', 0, 'Data integrity is solely an IT department responsibility with no HIM/coding involvement');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d5dc9d12-4bda-40cb-92ac-60e6411b4f19', '40ac3387-e23d-49c5-8cc3-737a66a97053', 1, 'HIM/coding professionals play an active role in monitoring for data quality issues (e.g., copy-forward/copy-paste documentation errors, template-driven over-documentation, duplicate records) that can compromise the accuracy of information used for coding and reporting');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0ee9ba7a-7a8f-46b6-ab6b-5935decd4dea', '40ac3387-e23d-49c5-8cc3-737a66a97053', 2, 'Coders should never review EHR-generated documentation for quality concerns');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('98360e42-5fc1-44e5-b5c7-074ad9a43003', '40ac3387-e23d-49c5-8cc3-737a66a97053', 3, 'Data integrity concerns apply only to paper records, not EHR systems');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d1e36b9a-00af-4e7b-a54d-34042552e8ee', '97668507-59c8-4cd8-8fca-5604e7ca7be0', 0, 'To store only billing codes for a facility');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cc6d6b6e-5725-49f2-b40e-d6122463c71a', '97668507-59c8-4cd8-8fca-5604e7ca7be0', 1, 'To maintain a unique identifier and demographic-matching system ensuring each patient''s records across encounters (and potentially across facilities/systems) are correctly linked to that one patient, reducing duplicate or fragmented records');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e17b33a2-6c11-4ae9-b5f9-920b49e68cdb', '97668507-59c8-4cd8-8fca-5604e7ca7be0', 2, 'To function as the encoder/grouper software');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c88414fd-8e99-4d74-9a13-ee9b7102b799', '97668507-59c8-4cd8-8fca-5604e7ca7be0', 3, 'To replace the need for any patient consent processes');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0b01750b-94eb-458c-adee-7bdfd208b1ae', 'e08969cc-9f86-446e-94eb-8ffc97d7bd7a', 0, 'Manually re-typing every physician note by a human transcriptionist before coding');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8f620d75-0f81-4ed4-9ee2-fd1d4c664e1d', 'e08969cc-9f86-446e-94eb-8ffc97d7bd7a', 1, 'Analyzing free-text clinical documentation to identify and extract clinically relevant terms/concepts that can be mapped to candidate codes for coder review');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('96409d23-27d1-4f94-a64d-811f307fb383', 'e08969cc-9f86-446e-94eb-8ffc97d7bd7a', 2, 'Automatically calling the patient to confirm their diagnosis');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d4a5eba5-9402-4e43-94e2-d0279cfb3b29', 'e08969cc-9f86-446e-94eb-8ffc97d7bd7a', 3, 'Replacing ICD-10-CM/PCS classification systems entirely with a new coding system');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2baf6d4d-f58e-433b-95d9-5301f66dd7a9', '41584bb6-b50f-41dd-aed0-c71d53143d02', 0, 'The EHR/clinical documentation system, the abstracting system, and the billing/claims system, since disconnected systems requiring duplicate manual data entry increase both workload and error risk');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b232ab43-4860-4b0e-b395-933fcf7c5aa9', '41584bb6-b50f-41dd-aed0-c71d53143d02', 1, 'Only the parking garage access system');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c6b8edcd-3dfc-4503-a3f0-5335a86d18ab', '41584bb6-b50f-41dd-aed0-c71d53143d02', 2, 'Only the cafeteria point-of-sale system');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8c7be6a4-a2aa-470b-9516-7200df0a9aa8', '41584bb6-b50f-41dd-aed0-c71d53143d02', 3, 'No other systems; encoders function entirely in isolation');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7eac6eac-90cf-4a0a-90d9-af290c3479e0', '878abfc0-8e84-49eb-965a-9d1507e768ac', 0, 'A cosmetic feature with no real compliance function');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cdbd376b-f347-404b-a297-0a9af58ada83', '878abfc0-8e84-49eb-965a-9d1507e768ac', 1, 'A system log recording who accessed/modified specific records or documentation and when, supporting both security monitoring (detecting inappropriate access) and documentation-integrity review (tracking when entries/amendments were made)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('dfcf9f1c-48ef-4bf4-ba3d-a3b7281b406a', '878abfc0-8e84-49eb-965a-9d1507e768ac', 2, 'A feature used only for billing reconciliation, unrelated to access monitoring');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0a502e40-cd23-466e-8402-97a1ba5cfe8a', '878abfc0-8e84-49eb-965a-9d1507e768ac', 3, 'A tool that automatically deletes old records after a set period');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d6c92eb2-3ab2-4ff0-ae36-748b83ed660c', '093042ee-1b7f-4dec-856d-1832442518a2', 0, 'Granularity refers only to the physical storage size of the database');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1ef0cb52-a650-4c2d-bb4d-ffe337409b2d', '093042ee-1b7f-4dec-856d-1832442518a2', 1, 'Granularity refers to the level of detail/specificity captured in discrete data fields (e.g., a structured ''laterality'' field vs. free text alone), which affects how effectively that data can be used for accurate CAC code suggestions, quality reporting, or analytics');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('149e6259-1c3c-41bf-b52b-005199cbbab1', '093042ee-1b7f-4dec-856d-1832442518a2', 2, 'Granularity is a term used only in radiology imaging, not general HIM data');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e7b237a5-074f-4fe3-8428-b4802706b568', '093042ee-1b7f-4dec-856d-1832442518a2', 3, 'Higher granularity always means worse system performance with no benefit');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b6ad9f9a-d3fc-4e47-8335-ee1e2cdaf375', 'af8274a3-29b8-477f-a671-81ac9fc47c39', 0, 'No real risk exists; free text always converts perfectly to structured codes automatically');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('649e7810-df4a-4f8a-80c3-68b730b81b6c', 'af8274a3-29b8-477f-a671-81ac9fc47c39', 1, 'Historical free-text entries may not map cleanly or accurately to structured codes during migration, risking data loss, miscoding, or loss of clinically important nuance if the mapping/conversion process isn''t carefully validated');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('88625382-0d0b-4dfa-a502-4ca4dee62693', 'af8274a3-29b8-477f-a671-81ac9fc47c39', 2, 'This scenario only affects IT staff, with no HIM/coding validation role');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ef38aed6-3339-4416-99fb-a40534dfb535', 'af8274a3-29b8-477f-a671-81ac9fc47c39', 3, 'Structured data is always inferior to free text for coding purposes');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('062d6832-0067-4435-8dab-0a92fd1bc74d', 'ca379f6a-d96b-4a01-aa9c-aa921753d1b1', 0, 'They are identical systems serving identical purposes with no distinction');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('dd117215-5a09-4d6d-b5d5-382693e8d691', 'ca379f6a-d96b-4a01-aa9c-aa921753d1b1', 1, 'SNOMED CT is a granular clinical reference terminology designed to represent detailed clinical concepts (often used within EHR documentation/data capture and for cross-mapping), while ICD-10-CM is a classification system designed primarily for statistical grouping, reporting, and reimbursement purposes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d773f145-b494-44c1-83c0-da9edc14d78d', 'ca379f6a-d96b-4a01-aa9c-aa921753d1b1', 2, 'ICD-10-CM is used only for laboratory results, never diagnoses');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e6d4e1bc-786e-49d2-9e81-493ae919a10a', 'ca379f6a-d96b-4a01-aa9c-aa921753d1b1', 3, 'SNOMED CT has no relevance to HIM/coding operations at all');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('dad7960e-095b-4878-9388-ec321e1e2342', 'ffca57b0-08c3-4bc3-86c0-320a492c5557', 0, 'Software updates are unnecessary since code sets never change');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('82a14718-f9d6-4bb9-910d-7a90c3402880', 'ffca57b0-08c3-4bc3-86c0-320a492c5557', 1, 'The facility''s HIM/coding leadership should coordinate with IT/vendor teams to ensure encoder, CAC, and grouper software are updated with the current year''s code set and logic changes before the effective date, and validate the update through testing rather than assuming automatic accuracy');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('781bc356-6eb9-4c20-b82b-ba3546124111', 'ffca57b0-08c3-4bc3-86c0-320a492c5557', 2, 'Updates should be applied only if a payer specifically requests them');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('28ec587d-4493-4682-a4ed-2d49874a5fd2', 'ffca57b0-08c3-4bc3-86c0-320a492c5557', 3, 'Code set updates are solely the vendor''s responsibility, requiring no facility-side validation at all');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
